#define min(x, y) ((x < y) ? (x) : (y))
#define max(x, y) ((x > y) ? (x) : (y))

double findMedianSortedArrays(int* nums1, int nums1Size, int* nums2, int nums2Size){
        int* A = nums1;
        int* B = nums2;
        int ASize = nums1Size;
        int BSize = nums2Size;

        int total = nums1Size + nums2Size;
        int half = total / 2;

        if(nums2Size < nums1Size)
        {
            A = nums2;
            B = nums1;
            ASize = nums2Size;
            BSize = nums1Size;
        }

        int l = 0;
        int r = ASize - 1;

        while(true)
        {
            int i = l + ((r - l - 2 + 1) / 2); // A Mid, round down instead of rounding towards 0
            int j = half - i - 2;      // B Mid


            int Aleft = i >= 0 ? A[i] : INT_MIN;
            int Aright = (i + 1) < ASize ? A[i + 1] : INT_MAX;
            int Bleft = j >= 0 ? B[j] : INT_MIN;
            int Bright = (j + 1) < BSize ? B[j + 1] : INT_MAX;

            // partition is correct
            if(Aleft <= Bright && Bleft <= Aright)
            {
                // Odd
                if(total % 2)
                {
                    return min(Aright, Bright);
                }

                // Even
                return (max(Aleft, Bleft) + min(Aright, Bright)) / 2.0;
            }
            else if(Aleft > Bright)
            {
                r = i - 1;
            }
            else
            {
                l = i + 1;
            }
        }

}

/*
Given a string s, return the longest palindromic substring in s.
Time: O(n^2)
Space: O(1)
*/

char* longestPalindrome(char * s){
    int pos=0;
    int lenmax=1;
    for (int i=0; s[i]!='\0'; i++){
        int g=i, d=i;
        while (g>=0 && s[d]!='\0' && s[g]==s[d]){
            g-=1;
            d+=1;
        }
        d--;
        g++;
        if (d-g>=lenmax){
            lenmax=d-g+1;
            pos=g;
        }
        g=i,d=i+1;
        while (g>=0 && s[d]!='\0' && s[g]==s[d]){
            g-=1;
            d+=1;
        }
        d--;
        g++;

        if (d-g>=lenmax){
            lenmax=d-g+1;
            pos=g;
        }
    }
    char* new_s = (char*)malloc(sizeof(char)*(lenmax+1));
    new_s[lenmax]='\0';
    for (int i=0; i<lenmax; i++){
        new_s[i]=s[i+pos];
    }
    return new_s;
}

int reverse(int x){
    int res = 0;

    while (x) {
        int digit = x % 10;
        if ((res > INT_MAX / 10) ||
        (res < INT_MIN / 10) ||
        (res == INT_MAX / 10 && digit > INT_MAX  % 10) ||
        (res == INT_MIN && digit > INT_MIN % 10)) {
            return 0;
        } else {
            res *= 10;
        }
        res += digit;

        x = x / 10;
    }

    return res;
}

bool isPalindrome(int x){
    if (x < 0) {
        return false;
    }
    long div = 1;
    while (x >= 10 * div) {
        div *= 10;
    }

    while (x) {
        int right = x % 10;
        int left = x / div;

        if (left != right) {
            return false;
        }

        x = (x % div) / 10;
        div /= 100;
    }

    return true;
}

bool isMatch(char *s, char *p) {
    int m = strlen(s);
    int n = strlen(p);

    bool dp[m + 1][n + 1];
    memset(dp, false, sizeof(dp));
    dp[0][0] = true;

    for (int j = 1; j <= n; j++) {
        if (p[j - 1] == '*') {
            dp[0][j] = dp[0][j - 2];
        }
    }

    for (int i = 1; i <= m; i++) {
        for (int j = 1; j <= n; j++) {
            if (p[j - 1] == s[i - 1] || p[j - 1] == '.') {
                dp[i][j] = dp[i - 1][j - 1];
            } else if (p[j - 1] == '*') {
                dp[i][j] = dp[i][j - 2] || ((s[i - 1] == p[j - 2] || p[j - 2] == '.') && dp[i - 1][j]);
            }
        }
    }

    return dp[m][n];
}

int maxArea(int* height, int heightSize){
    int left = 0;
    int right = heightSize - 1;
    int res = 0;

    while (left < right) {
        res = max(res, min(height[left], height[right]) * (right - left));
        if (height[left] < height[right]) {
            left += 1;
        }
        else if (height[right] <= height[left]) {
            right -= 1;
        }
    }
    return res;
}

