int romanToInt(char * s){
    int len = 0;
    int sum = 0;
    int valueCurrent, valueNext;

    len = strlen(s);

    for(int i=0; i<len; i++) {

        valueCurrent = value(s[i]);

        if((i+1) < len) {
            valueNext = value(s[i+1]);
        }
        else {
            valueNext = 0;
        }

        if(valueNext > valueCurrent) {
            sum = sum - valueCurrent;
        }
        else {
            sum = sum + valueCurrent;
        }
    }

    return sum;
}

char * longestCommonPrefix(char ** strs, int strsSize){
    int commonPrefixCount = 0;
    int firstStrSize = strlen(strs[0]);

    for(int i = 0; i < firstStrSize; i++)
    {
        for(int s = 1; s < strsSize; s++)
        {
            if(i == strlen(strs[s]) || strs[0][i] != strs[s][i])
            {
                // Add null terminator after the last common prefix char
                strs[0][commonPrefixCount] = '\0';
                return strs[0];
            }
        }

        commonPrefixCount++;
    }

    return strs[0];
}

