struct ListNode* removeNthFromEnd(struct ListNode* head, int n){
    if (head->next == NULL) {
        return head->next;
    }

    struct ListNode* slow = head;
    struct ListNode* fast = head;

    while (n--) {
        fast = fast->next;
    }

    if (fast != NULL) {
        while (fast->next != NULL) {
            slow = slow->next;
            fast = fast->next;
        }
        struct ListNode* tmp = slow->next;
        slow->next = tmp->next;
        free(tmp);
    }
    else {
        slow->val = slow->next->val;
        struct ListNode* tmp = slow->next;
        slow->next = tmp->next;
        free(tmp);
    }

    return head;
}

struct Node {
    char val;
    struct Node* next;
};

struct Stack {
    struct Node* head;
    size_t len;
};

struct Node* Node(char val, struct Node* next) {
    struct Node* root = (struct Node*)malloc(sizeof(struct Node));
    root -> next = next;
    root -> val = val;
    return root;
}

struct Stack* Stack() {
    struct Stack* stack = (struct Stack*)malloc(sizeof(struct Stack));
    stack -> len = 0;
    stack -> head = NULL;
    return stack;
}

void append(struct Stack* stack, char val) {
    struct Node* node = Node(val, stack -> head);
    stack -> head = node;
    stack -> len += 1;
}

char pop(struct Stack* stack) {
    if (stack -> head == NULL) {
        return NULL;
    }
    char val = stack -> head -> val;
    struct Node* deleteNode = stack -> head;
    stack -> head = stack -> head -> next;
    stack -> len -= 1;
    free(deleteNode);
    return val;
}

void freeStack(struct Stack* stack) {
    while (pop(stack) != NULL) {
        pop(stack);
    }
    free(stack);
}

char opposite_parenthesis(char closing) {
    char opening = NULL;
    if (closing == ')') {
        opening = '(';
    } else if (closing == '}') {
        opening = '{';
    } else if (closing == ']') {
        opening = '[';
    }
    return opening;
}

bool isValid(char * s){

    struct Stack* stack = Stack();
    char* chr;

    for (chr = s; *chr != '\0'; chr++) {
        if (opposite_parenthesis(*chr) == NULL) {
            append(stack, *chr);
        } else if (stack -> len != 0 && opposite_parenthesis(*chr) == pop(stack)) {
            continue;
        } else {
            return false;
        }
    }
    bool result = stack -> len == 0;
    freeStack(stack);
    return result;
}

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     struct ListNode *next;
 * };
 */


struct ListNode* mergeTwoLists(struct ListNode* list1, struct ListNode* list2){

    if (list1 == NULL && list2 == NULL) {
        return NULL;
    } else if (list1 != NULL && list2 == NULL) {
        return list1;
    } else if (list2 != NULL && list1 == NULL) {
        return list2;
    }

    struct ListNode* temp_node = NULL;

    if (list1 -> val < list2 -> val) {
        temp_node = list1;
        list1 = list1 -> next;
    } else {
        temp_node = list2;
        list2 = list2 -> next;
    }

    struct ListNode* root = temp_node;

    while((list1 != NULL) || (list2 != NULL)) {

        if ((list2 == NULL) || ((list1 != NULL) && (list1 -> val < list2 -> val))) {
            temp_node -> next = list1;
            list1 = list1 -> next;
        } else {
            temp_node -> next = list2;
            list2 = list2 -> next;
        }
        temp_node = temp_node -> next;
    }

    return root;
}

