/**
 * Time: O(n.log(k))
 * Space: O(1)
 */

typedef struct ListNode ListNode;

ListNode* mergeLists(ListNode* l1, ListNode* l2)
{
    ListNode dummy;
    dummy.next = NULL;
    ListNode* tail = &dummy;

    while(l1 && l2)
    {
        if(l1->val < l2->val)
        {
            tail->next = l1;
            l1 = l1->next;
        }
        else
        {
            tail->next = l2;
            l2 = l2->next;
        }

        tail = tail->next;
    }

    if(l1)
    {
        tail->next = l1;
    }
    else if(l2)
    {
        tail->next = l2;
    }

    return dummy.next;
}

struct ListNode* mergeKLists(struct ListNode** lists, int listsSize){

    if(listsSize == 0)
    {
        return NULL;
    }

    while(listsSize > 1)
    {
        ListNode** mergedLists;
        size_t mergedListsIndex = 0;

        for(size_t i = 0; i < listsSize; i += 2)
        {
            ListNode* l1 = lists[i];
            ListNode* l2 = (i + 1) < listsSize ? lists[i + 1] : NULL;

            mergedLists[mergedListsIndex++] = mergeLists(l1, l2);
        }

        lists = mergedLists;
        listsSize = (listsSize + 1) / 2;
    }

    return lists[0];
}

/*
  Given a linked list, swap every two adjacent nodes and return its head.
  You must solve the problem without modifying the values in the list's nodes (i.e., only nodes themselves may be changed.)

  Ex. Input: head = [1,2,3,4]
      Output: [2,1,4,3]

  Time  : O(N)
  Space : O(1)
*/

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     struct ListNode *next;
 * };
 */
struct ListNode* swapPairs(struct ListNode* head) {
    if (head == NULL || head->next == NULL)
        return head;

    struct ListNode *new_head = head->next;
    struct ListNode *prev = NULL;

    while (head != NULL && head->next != NULL) {
        struct ListNode *next_pair = head->next->next;
        struct ListNode *second = head->next;

        if (prev != NULL)
            prev->next = second;

        second->next = head;
        head->next = next_pair;

        prev = head;
        head = next_pair;
    }

    return new_head;
}

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     struct ListNode *next;
 * };
 */

typedef struct ListNode ListNode;

ListNode* getKth(ListNode* curr, int k)
{
    while(curr && k > 0)
    {
        curr = curr->next;
        k--;
    }

    return curr;
}

struct ListNode* reverseKGroup(struct ListNode* head, int k){
    ListNode dummy = { 0, head };
    ListNode* prevGroupTail = &dummy;

    while(true)
    {
        ListNode* kth = getKth(prevGroupTail, k);

        if(!kth)
        {
            break;
        }

        ListNode* nextGroupHead = kth->next;


        // Reverse group
        ListNode* prev = nextGroupHead;
        ListNode* curr = prevGroupTail->next;
        while(curr != nextGroupHead)
        {
            ListNode* temp = curr->next;
            curr->next = prev;
            // Increment the pointers
            prev = curr;
            curr = temp;
        }


        ListNode* lastNodeInCurrentGroup = prevGroupTail->next;
        // Connect the previous group to the current group
        prevGroupTail->next = kth;  // kth is now the first node in the group
        // Update prevGroupTail for the next iteration of the loop
        prevGroupTail = lastNodeInCurrentGroup;

    }

    return dummy.next;
}

