    int i = 0;

    while(i < numsSize){
        int val = nums[i];
        if(val > 0) val = val - 1;

        if(nums[i] > 0 && nums[i] < numsSize && nums[i] != nums[val]){
            int temp = nums[i];
            nums[i] = nums[val];
            nums[val] = temp;
        }
        else i++;
