char *StrToKey(char *str) {
    int size = strlen(str);
    char c[26] = {0};
    char *key = malloc(size + 1);
    char *k = key;
    size_t i, j;

    for (i = 0; i < size; i++) {
        c[str[i] - 'a']++;
    }

    for (i = 0; i < 26; i++) {
        for (j = 0; j < c[i]; j++) {
            *k++ = 'a' + i;
        }
    }
    *k = '\0';
