int can_ce_placed(int i, int j, int n, int** board) {
    for (int k=i-1; k>=0; k--)
        if (board[k][j])
            return false;
    for (int k=j-1; k>=0; k--)
        if (board[i][k])
            return false;
    int m = min(i, j)+1;
    for (int k=1; k<m; k++)
        if (board[i-k][j-k])
            return false;
    m = min(i+1, n-j);
    for (int k=1; k<m; k++)
        if (board[i-k][j+k])
            return false;
    return true;
}

int backtracking(int i, int n, int** board) {
    if (i==n)
        return 1;
    int cpt = 0;
    for (int k=0; k<n; k++){
        if (can_ce_placed(i, k, n, board)){
            board[i][k] = 1;
            cpt += backtracking(i+1, n, board);
            board[i][k] = 0;
        }
    }
    return cpt;
}

