    if(dp[posX][posY] != -1) return dp[posX][posY];

    int right = ways(posX + 1, posY, m, n); // moves to right corner.

    int bottom = ways(posX, posY + 1, m, n);// moves to bottom corner.

    dp[posX][posY] = right + bottom;

    return dp[posX][posY];
}

