}

/*
    Given a 2d matrix if an element is 0, set it's entire row and column to 0 as
    well.
    Ex. matrix = [[ 1,  1,  1],         [[ 1,  0,  1],
                  [ 1,  0,  1],    ->    [ 0,  0,  0],
                  [ 1,  1,  1]]          [ 1,  0,  1]]

    An identical result matrix can be initialised and then updated according to
    the zeros values in the original matrix. However, this would take O(m*n)
    space, which can be improved.

    By doing the updations in the same matrix, space complexity becomes O(1). We
    reserve the top most row as marker, they will signify whether the
    corresponding column has a zero or not. Similarly the first column, will do
    the same for the rows.

    An additional variable is needed as the m[0][0] is common in both the first
    row and first column.

    Time: O(m*n) where m, n are the matrix dimensions
    Space: O(1)
*/

void setZeroes(int** matrix, int matrixSize, int* matrixColSize){
    int ROW = matrixSize;
    int COL = *matrixColSize;
    bool rowZero = false;

    for (int r = 0; r < ROW; ++r) {
        for (int c = 0; c < COL; ++c) {
            if (matrix[r][c] == 0) {
                matrix[0][c] = 0;
                if (r > 0)
                    matrix[r][0] = 0;
                else
                    rowZero = true;
            }
        }
    }

    for (int r = 1; r < ROW; ++r) {
        for (int c = 1; c < COL; ++c) {
            if (matrix[0][c] == 0 || matrix[r][0] == 0)
                matrix[r][c] = 0;
        }
    }

    // Set first column as zeros if matrix[0][0] is set
    if (matrix[0][0] == 0) {
        for (int r = 0; r < ROW; ++r) {
            matrix[r][0] = 0;
        }
    }

    // Set first row as zeros if rowZero is true
    if (rowZero) {
        for (int c = 0; c < COL; ++c) {
            matrix[0][c] = 0;
        }
    }
}

/*
    Given a 2d matrix, where,
    1. the rows are sorted from left to right,
    2. the last element of each row is less than first element of next row

    Find an efficient method to search for a given element in this array
    Ex. matrix = [[ 1,  3,  5,  7],
                  [10, 11, 16, 20],
                  [23, 30, 34, 60]],
                target = 3 -> true (3 exists)

    The 2D matrix can be thought of as a 1D array if the rows are arranged
    sequentially. And given the conditions, the 1D array will also be sorted.
    So, binary search can be used to solve this problem with indexes (row, col)
    rather than one.

    Time: O(log(mn))
    Space: O(1)
*/

bool searchMatrix(int** matrix, int matrixSize, int* matrixColSize, int target){
    int m = matrixSize;
    int n = *matrixColSize;

    int low = 0;
    int high = m*n - 1;

    int mid = low + (high - low)/2;


    while (low <= high) {
        int row = mid / n;
        int col = mid % n;

        if (matrix[row][col] > target)
            high = mid - 1;
        else if (matrix[row][col] < target)
            low = mid + 1;
        else
            return true;
        mid = low + (high - low)/2;

    }

    return false;

}

/*
Given an array nums with n objects colored red, white, or blue, sort
them in-place so that objects of the same color are adjacent, with
the colors in the order red, white, and blue.

Space: O(1)
Time: O(n) (one-pass algorithm)
*/


void swap(int* nums, int a, int b) {
    int tmp = nums[a];
    nums[a] = nums[b];
    nums[b] = tmp;
}

void sortColors(int* nums, int numsSize){
    int pos1 = 0;
    int right = numsSize-1;
    int left = 0;
    // Before index (left-pos1) -> only 0
    // Between indexes (left-pos1) and left -> only 1
    // After indexe left -> only 2
    while (left<=right) {
        if (nums[left]==2) {
            swap(nums, left, right);
            right--;
        } else if (nums[left]==0) {
            swap(nums, left, left-pos1);
            left++;
        } else {
            pos1++;
            left++;
        }
    }
}

/*
Given two strings s and t of lengths m and n respectively, return the minimum window substring of s such that every
character in t (including duplicates) is included in the window. If there is no such substring, return the empty string "".
Space: O(1)
Time: O(n+m) where n is the length of s and m the length of t
*/

char * minWindow(char * s, char * t){
    int alpha[59] = {0};
    int need = 0;
    for (int i=0; t[i]!='\0'; i++) { // Initialise the alphabet
        if (alpha[t[i]-'A']==0)
            need++;
        alpha[t[i]-'A']--;
    }
    int maxLen = 100001;
    int pos=0;
    int i=0, j=0;
    while (s[j]!='\0') {
        alpha[s[j]-'A']++;
        if (alpha[s[j]-'A']==0) {
            need--;
            if (need==0) {
                while (alpha[s[i]-'A']>0) {
                    alpha[s[i]-'A']--;
                    i++;
                }
                if ((j-i+1)<maxLen) {
                    pos = i;
                    maxLen = j-i+1;
                }
                alpha[s[i]-'A']--;
                need++;
                i++;
            }
        }
        j++;
    }

    if (maxLen==100001) { // No substring found
        char* ans = malloc(sizeof(char));
        ans[0] = '\0';
        return ans;
    } else {
        char* ans = malloc(sizeof(char)*(maxLen+1));
        for (int i=0; i<maxLen; i++)
            ans[i] = s[i+pos];
        ans[maxLen] = '\0';
        return ans;
    }
}

/**
 * Return an array of arrays of size *returnSize.
 * The sizes of the arrays are returned as *returnColumnSizes array.
 * Note: Both returned array and *columnSizes array must be malloced, assume caller calls free().
 */

int nCr(int* factorials, int n, int r) {
    return (int)(factorials[n] / (factorials[r] * (factorials[n - r])));
}

int** subsets(int* nums, int numsSize, int* returnSize, int** returnColumnSizes){

    int* factorials = (int*)malloc((numsSize + 1) * sizeof(int));
    factorials[0] = 1;
    factorials[1] = 1;

    for (int i = 2; i < (numsSize + 1); i++) {
        factorials[i] = factorials[i - 1] * i;
    }

    int combinations = 0;
    for (int i = 0; i < (numsSize + 1); i++) {
        combinations += nCr(factorials, numsSize, i);
    }
    *returnSize = combinations;

    int** result = (int**)malloc(combinations * sizeof(int*));
    returnColumnSizes[0] = (int*)malloc(combinations * sizeof(int));
    returnColumnSizes[0][0] = 0;

    int current_size = 1;
    int lead = 1;
    for (int i = 0; i < numsSize; i++) {
        for (int j = 0; j < current_size; j++) {
            int* new_subset = (int*)malloc((returnColumnSizes[0][j] + 1) * sizeof(int));
            for (int k = 0; k < returnColumnSizes[0][j]; k++) {
                new_subset[k] = result[j][k];
            }
            new_subset[returnColumnSizes[0][j]] = nums[i];
            result[lead] = new_subset;
            returnColumnSizes[0][lead] = (returnColumnSizes[0][j] + 1);
            lead += 1;
        }
        current_size = lead;
    }
    free(factorials);
    return result;
}

/*
Given an m x n grid of characters board and a string word, return true if word exists in the grid.
Time: O(n*m*(3^h)) where h is the length of the word
Space: O(1)

*/

bool dfs(char** board, int n, int m, int i, int j, char* word) {
    if (word[0]=='\0' || word[1]=='\0')
        return true;
    char c = board[i][j];
    board[i][j] = 0;
    if (i>0 && board[i-1][j]==word[1]){
        if (dfs(board, n, m, i-1, j, word+1)){
            board[i][j] = c;
            return true;
        }
    }
    if (j>0  && board[i][j-1]==word[1]){
        if (dfs(board, n, m, i, j-1, word+1)){
            board[i][j] = c;
            return true;
        }
    }
    if (i<(n-1) && board[i+1][j]==word[1]){
        if (dfs(board, n, m, i+1, j, word+1)){
            board[i][j] = c;
            return true;
        }
    }
    if (j<(m-1) && board[i][j+1]==word[1]){
        if (dfs(board, n, m, i, j+1, word+1)){
            board[i][j] = c;
            return true;
        }
    }
    board[i][j] = c;
    return false;
}


bool exist(char** board, int boardSize, int* boardColSize, char * word){
    int m = (*boardColSize), i, j;
    for (i=0; i<boardSize; i++) {
        for (j=0; j<m; j++) {
            if (board[i][j]==word[0]) {
                if (dfs(board, boardSize, m, i, j, word)){
                    return true;
                }
            }
        }
    }
    return false;
}

int removeDuplicates(int* nums, int numsSize) {
  int k = 1;
  int sequence = 0;
  for (int pos = 1; pos < numsSize; pos++) {
    int repNum = nums[pos] == nums[k - 1];
    if (sequence && repNum)
      k--;
    else if (repNum)
      sequence = 1;
    else
      sequence = 0;
    nums[k] = nums[pos];
    k++;
  }
  return k;
}

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     struct ListNode *next;
 * };
 */

// Time: O(n)
// Space: O(1)
struct ListNode* deleteDuplicates(struct ListNode* head){
    struct ListNode* cur = head;
    while (cur) {
        while (cur->next && cur->next->val == cur->val) {
            cur->next = cur->next->next;
        }
        cur = cur->next;
    }
    return head;
}

const int MAX_N = 1e5 + 5;
struct Stack
{
    int top;
    int capacity;
    int *array;
};

struct Stack *createStack()
{
    struct Stack *stack = (struct Stack *)malloc(sizeof(struct Stack));
    stack->capacity = MAX_N;
    stack->top = -1;
    stack->array = (int *)malloc(stack->capacity * sizeof(int));
    return stack;
}

int isFull(struct Stack *stack)
{
    return stack->top == stack->capacity - 1;
}

int isEmpty(struct Stack *stack)
{
    return stack->top == -1;
}

void push(struct Stack *stack, int val)
{
    if (isFull(stack))
        return;
    stack->array[++stack->top] = val;
}

void pop(struct Stack *stack)
{
    if (isEmpty(stack))
        return;
    --stack->top;
}

int peek(struct Stack *stack)
{
    if (isEmpty(stack))
        return INT_MIN;
    return stack->array[stack->top];
}

int max(int num1, int num2)
{
    return (num1 > num2) ? num1 : num2;
}

int largestRectangleArea(int *heights, int heightsSize)
{
    int ans = 0;
    struct Stack *st = createStack();
    for (int i = 0; i < heightsSize; i++)
    {
        while (!isEmpty(st) && heights[peek(st)] > heights[i])
        {
            int tp = peek(st);
            pop(st);
            int dist = (isEmpty(st) ? i : i - peek(st) - 1);
            ans = max(ans, dist * heights[tp]);
        }
        push(st, i);
    }
    while (!isEmpty(st))
    {
        int tp = peek(st);
        pop(st);
        int dist = (isEmpty(st) ? heightsSize : heightsSize - peek(st) - 1);
        ans = max(ans, dist * heights[tp]);
    }
    return ans;
}

/*
Merge nums1 and nums2 into a single array sorted in non-decreasing order.

Space: O(1)
Time: O(n+m)
*/

void merge(int* nums1, int nums1Size, int m, int* nums2, int nums2Size, int n){
    int i=m-1;
    int j=n-1;
    while (i>=0 || j>=0) {
        if (j<0){ // Only numbers from nums1 remain
            return;
        } else if (i<0) { // Only numbers from nums2 remain
            nums1[j] = nums2[j];
            j--;
        } else {
            if (nums1[i]>nums2[j]) {
                nums1[i+j+1] = nums1[i];
                i--;
            } else {
                nums1[i+j+1] = nums2[j];
                j--;
            }
        }
    }
}

void backtrack(int* nums, int numsSize, int start, int* subset, int subsetSize, int*** result, int* resultSize, int** resultColSizes) {
    // Add the current subset to the result set
    *result = (int**)realloc(*result, (*resultSize + 1) * sizeof(int*));
    (*result)[*resultSize] = (int*)malloc(subsetSize * sizeof(int));
    for (int i = 0; i < subsetSize; i++) {
        (*result)[*resultSize][i] = subset[i];
    }
    (*resultColSizes) = (int*)realloc(*resultColSizes, (*resultSize + 1) * sizeof(int));
    (*resultColSizes)[*resultSize] = subsetSize;
    (*resultSize)++;

    // Backtracking
    for (int i = start; i < numsSize; i++) {
        // Skip duplicates to avoid duplicates in subsets
        if (i > start && nums[i] == nums[i - 1]) {
            continue;
        }

        subset[subsetSize] = nums[i];
        backtrack(nums, numsSize, i + 1, subset, subsetSize + 1, result, resultSize, resultColSizes);
    }
}

int compare(const void* a, const void* b) {
    return *(int*)a - *(int*)b;
}

int** subsetsWithDup(int* nums, int numsSize, int* returnSize, int** returnColumnSizes) {
    qsort(nums, numsSize, sizeof(int), compare);
    int** result = NULL;
    int* resultColSizes = NULL;
    int* subset = (int*)malloc(numsSize * sizeof(int));
    *returnSize = 0;

    backtrack(nums, numsSize, 0, subset, 0, &result, returnSize, &resultColSizes);

    *returnColumnSizes = resultColSizes;
    free(subset);
    return result;
}

/*
Given a string s containing only digits, return the number
of ways to decode it.

Space: O(n)
Time: O(n)
*/

int numDecodings(char * s){
    int n = strlen(s);
    if (n==1)
        return s[0]!='0'; // if s is '0' then it's invalid
    int* dp = malloc(sizeof(int)*(n+1));
    dp[n] = 1; // Initialise the empty string
    dp[n-1] = s[n-1]=='0'?0:1; // If it begins with a '0' it's invalid
    for (int i=n-2; i>=0; i--) {
        if (s[i]=='0') { // Begin with a zero
            dp[i] = 0;
        } else if (s[i]=='1' || s[i]=='2') {
            if (s[i]=='2' && s[i+1]>='7')
                dp[i] = dp[i+2]; // Only one way to decode
            else
                dp[i] = dp[i+1] + dp[i+2]; // Two way to decode
        } else {
            dp[i] = dp[i+1]; // One way to decode
        }
    }
    return dp[0];
}

/*
Given the root of a binary tree, return the inorder traversal of its nodes' values.

Space: O(n)
Time: O(n)
*/

void fill_array(struct TreeNode* root, int* ans, int* pos) {
    // Fill the array with the inorder traversal order
    if (root==NULL)
        return;
    fill_array(root->left, ans, pos);
    ans[*pos] = root->val;
    *pos = *pos +1;
    fill_array(root->right, ans, pos);
}

int* inorderTraversal(struct TreeNode* root, int* returnSize){
    int* ans = malloc(sizeof(int)*101); // 101 as a length as we don't know the max and its inferior of 100
    *returnSize = 0; // Current position in the array
    fill_array(root, ans, returnSize);
    return ans;
}

/*
Given an integer n, return the number of structurally unique BST's
(binary search trees) which has exactly n nodes of unique values from 1 to n.

Space: O(n)
Time: O(n²)
*/

int numTrees(int n){
    int* dp = (int*)malloc(sizeof(int)*(n+1));
    dp[0]=dp[1]=1;
    for (int i=2; i<(n+1); i++){
        dp[i] = 0;
        for (int j=1; j<(i+1); j++){
            dp[i]+=dp[j-1]*dp[i-j];
        }
    }
    // We could free dp
    return dp[n];
}

bool isInterleave(char *s1, char *s2, char *s3) {
    int len1 = strlen(s1);
    int len2 = strlen(s2);
    int len3 = strlen(s3);

    // If the lengths of the input strings don't add up correctly, return false
    if (len1 + len2 != len3) {
        return false;
    }

    // Create a 2D DP array to store the results of subproblems
    bool dp[len1 + 1][len2 + 1];
    memset(dp, false, sizeof(dp));

    // Base case: empty strings can always interleave to form an empty string
    dp[0][0] = true;

    // Fill in the DP array
    for (int i = 0; i <= len1; i++) {
        for (int j = 0; j <= len2; j++) {
            // If s1 matches the interleaved portion of s3
            if (i > 0 && s1[i - 1] == s3[i + j - 1]) {
                dp[i][j] = dp[i][j] || dp[i - 1][j];
            }
            // If s2 matches the interleaved portion of s3
            if (j > 0 && s2[j - 1] == s3[i + j - 1]) {
                dp[i][j] = dp[i][j] || dp[i][j - 1];
            }
        }
    }

    return dp[len1][len2];
}

/*
