    int depth_left = dfs(root->left);
    int depth_right = dfs(root->right);

    if (depth_left == -1 || depth_right == -1 || abs(depth_left - depth_right) > 1) {
        return -1;
    }

    return max(depth_left, depth_right) + 1;
}

