/*
Given the root of a binary tree, return the maximum path sum of any non-empty path.
Time: O(n)
Space: O(1)

*/

int max(int a, int b) {
    return a>b?a:b;
}

int rec(struct TreeNode* t, int* m) { // Return the maximum path sum which uses t->Val
    if (t==NULL)
        return -1001;
    int r = rec(t->right, m);
    int l = rec(t->left, m);
    if (t->val>0)
        *m = max(*m, t->val+max(l+r, max(l, r)));
    else
        *m = max(*m, max(r, max(l, l+r+t->val)));
    return max(0, max(l, r))+t->val;
}

int maxPathSum(struct TreeNode* root){
    int m = root->val;
    int c = rec(root, &m);
    return max(c, m);
}

/*
    Time: O(n)
    Space: O(1)
*/

bool isPalindrome(char * s){
    int n = strlen(s);
    if (n==1) return true;

    int left = 0;
    int right = n-1;

    while (left < right) {
        if (isalnum(s[left]) && isalnum(s[right])) {
            char leftChar = tolower(s[left]);
            char rightChar = tolower(s[right]);

            if (leftChar != rightChar) {
                return false;
            }
            left++;
            right--;
        }

        if (!isalnum(s[left])) left++;
        if (!isalnum(s[right])) right--;
    }

    return true;
}

/*
Return the total sum of all root-to-leaf numbers.

Space: O(1)
Time: O(n)
*/

int dfs(struct TreeNode* r, int acc) {
    if (r==NULL)
        return acc;
    if (r->left==NULL && r->right==NULL)
        return acc*10 + r->val;
    if (r->left==NULL)
        return dfs(r->right, acc*10 + r->val);
    if (r->right==NULL)
        return dfs(r->left, acc*10 + r->val);
    return dfs(r->right, acc*10 + r->val) + dfs(r->left, acc*10 + r->val);
}

int sumNumbers(struct TreeNode* root){
    return dfs(root, 0);
}

/*
Given an m x n matrix board containing 'X' and 'O', capture all regions that are 4-directionally surrounded by 'X'.
Time: O(n^2)
Space: O(1)
*/


void dfsModifyBorder(char** board, int n, int m, int i, int j) {
    if (board[i][j]=='X')
        return;
    board[i][j]='T';
    if (i>0 && board[i-1][j]=='O')
        dfsModifyBorder(board, n, m, i-1, j);
    if (j>0 && board[i][j-1]=='O')
        dfsModifyBorder(board, n, m, i, j-1);
    if (i<(n-1) && board[i+1][j]=='O')
        dfsModifyBorder(board, n, m, i+1, j);
    if (j<(m-1) && board[i][j+1]=='O')
        dfsModifyBorder(board, n, m, i, j+1);
}

void reModifyBorder(char** board, int n, int m) {
    int i, j;
    for (i=0; i<n; i++){
        for (j=0; j<m; j++){
            if (board[i][j]=='O')
                board[i][j]='X';
            else if (board[i][j]=='T')
                board[i][j]='O';
        }
    }
}

void solve(char** board, int boardSize, int* boardColSize){
    int i, j;
    int m = (*boardColSize);
    int n1 = boardSize-1;
    int m1 = m-1;
    for (i=1; i<n1; i++) {
        dfsModifyBorder(board, boardSize, m, i, 0);
        dfsModifyBorder(board, boardSize, m, i, m1);
    }
    for (j=0; j<m; j++) {
        dfsModifyBorder(board, boardSize, m, 0, j);
        dfsModifyBorder(board, boardSize, m, n1, j);
    }
    reModifyBorder(board, boardSize, m);
}

/**
 * Definition for a Node.
 * struct Node {
 *     int val;
 *     int numNeighbors;
 *     struct Node** neighbors;
 * };
 */

struct Node* create_node(int val, int numNeighbors) {
    struct Node* node = (struct Node*)malloc(sizeof(struct Node));
    node -> val = val;
    node -> numNeighbors = numNeighbors;
    if (numNeighbors > 0) {
        node -> neighbors = (struct Node**)malloc(numNeighbors * sizeof(struct Node*));
    } else {
        node -> neighbors = NULL;
    }
    return node;
}

struct Node* clone_node(struct Node* s, struct Node** hashset) {

    if (s == NULL) return s;
    if (hashset[(s -> val) - 1] != NULL) return hashset[(s -> val) - 1];

    struct Node* new_node = create_node(s -> val, s -> numNeighbors);
    hashset[(s -> val) - 1] = new_node;
    for (int i = 0; i < s -> numNeighbors; i++) {
        new_node -> neighbors[i] = clone_node(s -> neighbors[i], hashset);
    }
    return new_node;
}

struct Node *cloneGraph(struct Node *s) {

    struct Node** hashset = (struct Node**)malloc(100 * sizeof(struct Node*));
    for (int i = 0; i < 100; i++) {
        hashset[i] = NULL;
    }
    struct Node* s_clone = clone_node(s, hashset);
    free(hashset);
    return s_clone;
}

int canCompleteCircuit(int* gas, int gasSize, int* cost, int costSize){
    // Find the totalGas and totalCost
    int totalGas = 0;
    int totalCost = 0;
    for (int i = 0; i < gasSize; i++) {
        totalGas += gas[i];
        totalCost += cost[i];
    }

    // If totalCost is more than totalGas, it is not possible to complete circuit
    if (totalGas < totalCost) {
        return -1;
    }

    int total = 0;
    int result = 0;
    for (int i = 0; i < gasSize; i++) {
        total += gas[i] - cost[i];
        if (total < 0) {
            total = 0;
            result = i + 1;
        }
    }
    return result;
}

int candy(int* ratings, int ratingsSize) {
    int* candies = (int*)malloc(sizeof(int) * ratingsSize);

    // Initialize all children with 1 candy
    for (int i = 0; i < ratingsSize; i++) {
        candies[i] = 1;
    }

    // First pass: from left to right
    for (int i = 1; i < ratingsSize; i++) {
        if (ratings[i] > ratings[i - 1]) {
            candies[i] = candies[i - 1] + 1;
        }
    }

    // Second pass: from right to left
    for (int i = ratingsSize - 2; i >= 0; i--) {
        if (ratings[i] > ratings[i + 1] && candies[i] <= candies[i + 1]) {
            candies[i] = candies[i + 1] + 1;
        }
    }

    // Calculate the total number of candies
    int totalCandies = 0;
    for (int i = 0; i < ratingsSize; i++) {
        totalCandies += candies[i];
    }

    free(candies);

    return totalCandies;
}

