/**
 * Definition for a Node.
 * struct Node {
 *     int val;
 *     struct Node *next;
 *     struct Node *random;
 * };
 */

/*
    Time: O(n)
    Space: O(1)
*/

typedef struct Node Node;
struct Node* copyRandomList(struct Node* head) {

        if(head == NULL)
        {
            return NULL;
        }

        /**
         * Insert each new node after each original node
         */
        Node* curr = head;
        while(curr)
        {
            // Create the new node
            Node* newNode = (Node*)malloc(sizeof(Node));
            newNode->val = curr->val;

            // Insert new node after the original node
            newNode->next = curr->next;
            curr->next = newNode;

            // Move curr to the next original node
            curr = curr->next->next;
        }


        /**
         * Add the random node for each new node
         */
        curr = head;
        Node* newNode = NULL;
        while(curr)
        {
            // The new node is the next node to the original node
            newNode = curr->next;

            if(curr->random)
            {
                newNode->random = curr->random->next;
            }
            else
            {
                newNode->random = NULL;
            }

            // Move curr to the next original node
            curr = curr->next->next;
        }

        /**
         * Separate the original nodes list from the new nodes list
         */
        Node* originalList = head;
        Node* copiedList = head->next;
        Node* copiedListHead = head->next;
        while(originalList)
        {
            originalList->next = originalList->next->next;
            if(copiedList->next)
            {
                copiedList->next = copiedList->next->next;
            }
            else
            {
                copiedList->next = NULL;
            }

            originalList = originalList->next;
            copiedList = copiedList->next;
        }


        return copiedListHead;
}

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     struct ListNode *next;
 * };
 */

bool Traverse(struct ListNode* slow, struct ListNode* fast) {

    if (slow == NULL || slow -> next == NULL) {
        return false;
    }

    if (fast == NULL || fast -> next == NULL) {
        return false;
    }

    if (slow == fast) {
        return true;
    }
    return Traverse(slow -> next, fast -> next -> next);
}


bool hasCycle(struct ListNode *head) {

    if (head == NULL) {
        return false;
    }

    return Traverse(head, head -> next);

}

/**
 * Given the head of a linked list, return the node where the cycle begins. If
 * there is no cycle, return null.
 *
 * There is a cycle in a linked list if there is some node in the list that can
 * be reached again by continuously following the next pointer. Internally, pos
 * is used to denote the index of the node that tail's next pointer is connected
 * to (0-indexed). It is -1 if there is no cycle. Note that pos is not passed as
 * a parameter.
 *
 * Do not modify the linked list.
 *
 * Constraints:
 *
 * The number of the nodes in the list is in the range [0, 104].
 * -105 <= Node.val <= 105
 * pos is -1 or a valid index in the linked-list.
 *
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     struct ListNode *next;
 * };
 *
 * Space: O(1)
 * Time: O(n)
 */

struct ListNode *detectCycle(struct ListNode *head) {
    struct ListNode *fast = head;
    struct ListNode *slow = head;

    if (!head)
        return NULL;

    while (fast->next && fast->next->next) {
        fast = fast->next->next;
        slow = slow->next;

        if (fast == slow) {
            /**
             * The index of the node cycle is located the same number of nodes
             * away from the start of the linked list and the intersection of
             * the slow and fast pointers.
             */
            struct ListNode *head_node = head;
            struct ListNode *intersection = slow;

            while (head_node != intersection) {
                head_node = head_node->next;
                intersection = intersection->next;
            }

            return intersection;
        }
    }

    return NULL;
}

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     struct ListNode *next;
 * };
 */

struct ListNode* reverse(struct ListNode* head) {
    struct ListNode* prev = NULL;
    struct ListNode* curr = head;
    struct ListNode* next = curr->next;

    while (curr != NULL) {
        next = curr->next;
        curr->next = prev;
        prev = curr;
        curr = next;
    }

    return prev;
}

void merge(struct ListNode* l1, struct ListNode* l2) {
    while (l1 != NULL) {
        struct ListNode* p1 = l1->next;
        struct ListNode* p2 = l2->next;

        l1->next = l2;
        if (p1 == NULL) {
            break;
        }
        l2->next = p1;

        l1 = p1;
        l2 = p2;
    }
}

void reorderList(struct ListNode* head){
    if (head->next == NULL) {
        return;
    }

    struct ListNode* prev = NULL;
    struct ListNode* slow = head;
    struct ListNode* fast = head;

    while (fast != NULL && fast->next != NULL) {
        prev = slow;
        slow = slow->next;
        fast = fast->next->next;
    }

    prev->next = NULL;

    struct ListNode* l1 = head;
    struct ListNode* l2 = reverse(slow);

    merge(l1, l2);
}

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     struct ListNode *next;
 * };
 */

struct ListNode* merge(struct ListNode *list1, struct ListNode *list2) {
    struct ListNode *head, *tail;

    if (!list1 || !list2) {
        if (!list1) {
            return list2;
        }
        return list1;
    }

    if (list1->val < list2->val) {
        head = list1;
        list1 = list1->next;
    } else {
        head = list2;
        list2 = list2->next;
    }
    tail = head;

    while (list1 && list2) {
        if (list1->val < list2->val) {
            tail->next = list1;
            list1 = list1->next;
        } else {
            tail->next = list2;
            list2 = list2->next;
        }
        tail = tail->next;
    }

    if (list1) {
        tail->next = list1;
    }

    if (list2) {
        tail->next = list2;
    }

    return head;
}

// Split a linked list in two halfs:
struct ListNode* split(struct ListNode* head) {
    struct ListNode *slow = head, *fast = head, *prev = NULL;

    while (fast && fast->next) {
        prev = slow;
        slow = slow->next;
        fast = fast->next->next;
    }

    prev->next = NULL;
    return slow;
}

struct ListNode* sortList(struct ListNode *head) {
    if (!head || !head->next) {
        return head;
    }

    return merge(sortList(head), sortList(split(head)));
}

int evalRPN(char ** tokens, int tokensSize){
    long int stk[tokensSize];

    int stkIndex = -1;

    for(int i = 0; i < tokensSize; i++)
    {
        if(strcmp(tokens[i], "+") == 0)
        {
            int first = stk[stkIndex];
            stkIndex--;
            int second = stk[stkIndex];

            stk[stkIndex] = first + second;
        }
        else if(strcmp(tokens[i], "-") == 0)
        {
            int first = stk[stkIndex];
            stkIndex--;
            int second = stk[stkIndex];

            stk[stkIndex] = second - first;
        }
        else if(strcmp(tokens[i], "*") == 0)
        {
            long first = stk[stkIndex];
            stkIndex--;
            int second = stk[stkIndex];

            stk[stkIndex] = first * second;

        }
        else if(strcmp(tokens[i], "/") == 0)
        {
            int first = stk[stkIndex];
            stkIndex--;
            int second = stk[stkIndex];

            stk[stkIndex] = second / first;
        }
        else
        {
            stkIndex++;
            stk[stkIndex] = atoi(tokens[i]);
        }

    }


    return stk[stkIndex];
}

int maxProduct(int* nums, int numsSize){
    int res = nums[0], curMin = 1, curMax = 1;

    for (int i = 0; i < numsSize; i++) {
        int temp = curMax * nums[i];
        curMax = max(max(nums[i] * curMax, nums[i] * curMin), nums[i]);
        curMin = min(min(temp, nums[i] * curMin), nums[i]);
        res = max(res, curMax);
    }
    return res;
}

// C doesn't have a built-in max function
int max(int a, int b) {
    return (a > b) ? a : b;
}

// C doesn't have a built-in min function
int min(int a, int b) {
    return (a < b) ? a : b;
}

int findMin(int* nums, int numsSize){
    // set the starting indicies to find minimum pivot
    int left = 0;
    int right = numsSize - 1;

    while (left < right) {
        // calculate middle index
        int middle = (left + right) / 2;

        // set the left or right index accordingly
        if (nums[middle] > nums[right]) {
            left = middle + 1;
        }
        else {
            right = middle;
        }
    }
    return nums[left];
}

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     struct ListNode *next;
 * };
 */
struct ListNode *getIntersectionNode(struct ListNode *headA, struct ListNode *headB) {
        struct ListNode *currA = headA;
        struct ListNode *currB = headB;

        while (currA && currB){
            if (currA == currB){
                return currA;
            }
            currA = currA->next;
            currB = currB->next;

            if (!currA && currB){
                currA = headB;
            }
            if (!currB && currA){
                currB = headA;
            }
        }
    return NULL;
}

int findPeakElement(int* nums, int numsSize) {
    int start = 0;
    int end = numsSize - 1;

    while(start < end){
        int mid = start + (end - start)/2;

        if(nums[mid] > nums[mid+1])
            end = mid;
        else if(nums[mid] < nums[mid+1])
            start = mid + 1;
    }

    return start;
}

/*
    Given a 1-indexed sorted int array & target:
    Return indices (added by 1) of 2 nums that add to target
    2 pointers, outside in, iterate i/j if sum is too low/high
    Time: O(n)
    Space: O(1)
*/

int* twoSum(int* numbers, int numbersSize, int target, int* returnSize){
    *returnSize = 2;
    int* ans = malloc(sizeof(int)*2);

    int i = 0;
    int j = numbersSize-1;
    int k;
    while (true) {
        k = numbers[i]+numbers[j]-target;
        if (k==0) { // numbers[i]+numbers[j] = target
            ans[0] = i+1;
            ans[1] = j+1;
            return ans;
        } else if (k>0) // numbers[i]+numbers[j] > target
            j--;
        else // numbers[i]+numbers[j] < target
            i++;
    }
}

/*
Given an array nums of size n, return the majority element.

Space: O(1)
Time: O(n)
*/

int majorityElement(int* nums, int numsSize){
    int candidate=nums[0];
    int count=1;
    for (int i=1; i<numsSize; i++) {
        if (candidate==nums[i]) {
            count++;
        } else {
            count--;
            if (count==0) {
                count=1;
                candidate=nums[i];
            }
        }
    }
    return candidate;
}

// Compare two numbers in a concatenated form.
// eg: 12 and 34 will be compared as 1234 vs 3412
int compareInt(const void *a, const void *b) {
    int i = 10;
    int j = 10;
    int x = *(int*)a;
    int y = *(int*)b;

    while (x /= 10) i *= 10;
    while (y /= 10) j *= 10;

    return  (((unsigned int)*(int*)b * i) + *(int*)a) > (((unsigned int)*(int*)a * j) + *(int*)b);
}

char * largestNumber(int* nums, int numsSize){
    char *res = NULL;
    int i, len, pos;

    if (numsSize < 0) {
        return res;
    }

    // Sort the array with specified comparaotor.
    qsort(nums, numsSize, sizeof(int), compareInt);

    // Caculate the length of the return string.
    len = 1;
    for (i = 0; i < numsSize; i++) len +=  snprintf(NULL, 0, "%d", nums[i]);
    res = calloc(len, sizeof(char));

    // If the firs element of sorted array is 0,
    // return a single digit of 0 no matter how long is the string.
    if (nums[0] == 0) {
        res[0] = '0';
        return res;
    }

    // Print all nums to the return string.
    pos = 0;
    for (i = 0; i < numsSize; i++) {
        pos += snprintf(res + pos, len, "%d", nums[i]);
    }

    return res;
}

uint32_t reverseBits(uint32_t n) {
    uint32_t res = 0;

    for (int i = 0; i < 32; i++) {
        res <<= 1;
        res |= n & 1;
        n >>= 1;
    }
    return res;
}

int hammingWeight(uint32_t n) {
    int res = 0;
    int bit = 0;
    while (n != 0) {
        bit = n & 1;
        if (bit == 1) {
            res++;
        }
        n = n >> 1;
    }
    return res;
}

int dp[105] = {};

int solve(int *nums, int n)
{
    if(n == 0) return nums[0];

    if(n < 0) return 0;

    if(dp[n] != -1) return dp[n];

    // robbing the present house and then move to the (n-2)th house
    int way1 = nums[n] + solve(nums, n-2);

    // skipping the present house and rob the (n-1)th house
    int way2 = 0 + solve(nums, n-1);

    if(way1 > way2) {
        dp[n] = way1;
    }
    else {
        dp[n] = way2;
    }

    return dp[n];
}

int rob(int* nums, int numsSize){

    // Initializing the dp array with initial value -1.
    for(int i = 0; i < 105; i++){
        dp[i] = -1 ;
    }

    return solve(nums, numsSize - 1);
}

/*
    Given a binary tree, return the right side view of it (the nodes which can
    be seen in front when looking from the right).
    Ex.     1 <-
           / \
          2   3 <-       -> [1, 3, 4]
           \   \
           5   4 <-


    The right side view is basically the last element at each level of the tree.
    So BFS is one way this problem can be solved.

    The solution below uses recursion, where on reaching a new depth we add that
    node as the right view for that depth. We recursively visit the right child
    before the left child to get the right view.

    Time: O(n)
    Space: O(n)
*/

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     struct TreeNode *left;
 *     struct TreeNode *right;
 * };
 */

void dfs(struct TreeNode* root, int* result, int* returnSize, int depth) {
    if (root == NULL)
        return;

    // If a new depth is reached, add the node as right view for that depth
    if (*returnSize <= depth) {
        *returnSize += 1;
        result[depth] = root->val;
    }

    // Visit the right child first then left child
    dfs(root->right, result, returnSize, depth+1);
    dfs(root->left, result, returnSize, depth+1);
}

/**
 * Note: The returned array must be malloced, assume caller calls free().
 */
int* rightSideView(struct TreeNode* root, int* returnSize) {
    // Size of result array depends on the depth of tree, which can be precomputed
    int* result = (int*) malloc(sizeof(int)*100);
    *returnSize = 0;

    dfs(root, result, returnSize, 0);

    return result;
}

int directions[][2] = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

void searchIsland(int row, int col, int rows, int cols, char** grid) {
    if ( row >= 0 && col >= 0 && row < rows && col < cols && grid[row][col] == '1') {
        for (int i = 0; i < 4; i++) {
            searchIsland(row + directions[i][0], col + directions[i][1], rows, cols, grid);
            grid[row][col] = '0';
        }
    }
}


int numIslands(char** grid, int gridSize, int* gridColSize){

    int rows = gridSize;
    int cols = gridColSize[0];

    int IslandCount = 0;

    for (int row = 0; row < rows; row++) {
        for (int col = 0; col < cols; col++) {
            if (grid[row][col] == '1') {
                searchIsland(row, col, rows, cols, grid);
                IslandCount++;
            }
        }
    }
    return IslandCount;
}




