int minSubArrayLen(int target, int* nums, int numsSize){
    int len=0;
    int i=0, j=0;
    int cpt=0;
    while (j<numsSize) {
        cpt += nums[j];
        if (cpt>=target) {
            if (len==0)
                len = j-i+1;
            while (cpt-nums[i] >= target) {
                cpt -= nums[i];
                len = min(len, j-i);
                i++;
            }
        }
        j++;
    }
    return len;
}

