        for (i = 0; i < 26; i++) {
            if (dict->c[i] && wordDictionarySearchR(dict->c[i], word, index + 1)) {
                return true;
            }
        }
    } else {
        j = c - 'a';
        if (!dict->c[j]) {
            return false;
        }
        return wordDictionarySearchR(dict->c[j], word, index + 1);
    }
    return false;
}

