int rob(int* nums, int numsSize){
    int n = numsSize;

    if (n == 1) {
        return nums[0];
    }

    int range1 = robber(nums, 0, n - 2);
    int range2 = robber(nums, 1, n - 1);

    return (range1 > range2) ? range1 : range2;
}

int robber(int* nums, int start, int end) {
    int prev = 0;
    int curr = 0;
    int next = 0;

    for (int i = start; i <= end; i++) {
        next = (curr > prev + nums[i]) ? curr : prev + nums[i];
        prev = curr;
        curr = next;
    }
    return curr;
}

// Function to partition the array using Lomuto partition scheme
int partition(int* nums, int left, int right) {
    int pivot = nums[right];
    int i = left - 1;

    for (int j = left; j < right; j++) {
        if (nums[j] <= pivot) {
            i++;
            int temp = nums[i];
            nums[i] = nums[j];
            nums[j] = temp;
        }
    }

    int temp = nums[i + 1];
    nums[i + 1] = nums[right];
    nums[right] = temp;

    return i + 1;
}

// Function to find the kth largest element using Quickselect
int quickSelect(int* nums, int left, int right, int k) {
    if (left <= right) {
        int partitionIndex = partition(nums, left, right);

        if (partitionIndex == k) {
            return nums[partitionIndex];
        } else if (partitionIndex > k) {
            return quickSelect(nums, left, partitionIndex - 1, k);
        } else {
            return quickSelect(nums, partitionIndex + 1, right, k);
        }
    }

    return -1; // Invalid case
}

int findKthLargest(int* nums, int numsSize, int k) {
    return quickSelect(nums, 0, numsSize - 1, numsSize - k);
}

