    HASH_ITER(hh, hash, elem, tmp) {
        HASH_DEL(hash, elem); free(elem);
    }

    return flag;
}

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     struct TreeNode *left;
 *     struct TreeNode *right;
 * };
 */

struct TreeNode *invertTree(struct TreeNode* root) {

    if (root == NULL) {
        return root;
    }
    struct TreeNode* inverted_right = invertTree(root -> right);
    struct TreeNode* inverted_left = invertTree(root -> left);
    root -> right = inverted_left;
    root -> left = inverted_right;
    return root;
}

/*
Given the root of a binary search tree, and an integer k, return
the kth smallest value (1-indexed) of all the values of the nodes
in the tree.

Space: O(log(n)) (due to recursive calls)
Time: O(n)
*/

void iterate_bst(struct TreeNode* t, int* pos, int* ans, int k) {
    if (t==NULL)
        return;
    iterate_bst(t->left, pos, ans, k);
    if ((*ans)!=-1) { // Already found
        return;
    } else if (*pos == k) { // t->val is the number wanted
        *ans = t->val;
        return;
    }
    *pos = *pos + 1;
    iterate_bst(t->right, pos, ans, k);
}

int kthSmallest(struct TreeNode* root, int k){
    int pos = 1; // Current pos in the tree
    int ans = -1;
    iterate_bst(root, &pos, &ans, k);
    return ans;
}

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     struct ListNode *next;
 * };
 */
bool isPalindrome(struct ListNode* head){

    // find middle of linked list
    struct ListNode *slow = head, *fast = head;
    while (fast && fast->next){
        slow = slow->next;
        fast = fast->next->next;
    }
    // reverse second half
    struct ListNode* prev = NULL;
    while (slow){
        struct ListNode* nxt = slow->next;
        slow->next = prev;
        prev = slow;
        slow = nxt;
    }

    // compare left and right
    struct ListNode *left=head, *right=prev;
    while (right){
        if (left->val != right->val){
            return false;
        }
        left = left->next;
        right = right->next;
    }
    return true;

}

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     struct TreeNode *left;
 *     struct TreeNode *right;
 * };
 */

struct TreeNode* lowestCommonAncestor(struct TreeNode* root, struct TreeNode* p, struct TreeNode* q) {

    int rootVal = root -> val;
    int pVal = p -> val;
    int qVal = q -> val;

    if (pVal > rootVal && qVal > rootVal) {
        return lowestCommonAncestor(root -> right, p, q);
    } else if (pVal < rootVal && qVal < rootVal) {
        return lowestCommonAncestor(root -> left, p, q);
    }
    return root;
}

/*
    Time: O(n)
    Space: O(n)

 * Note: The returned array must be malloced, assume caller calls free().
*/

int* productExceptSelf(int* nums, int numsSize, int* returnSize) {
    *returnSize = numsSize;

    int *result = (int *)malloc(sizeof(int)*numsSize);
    memset(result, 1, numsSize*sizeof(result[0])); // Fill up result array with 1s

    int pre = 1;
    for(int i=0; i<numsSize; i++) {
        result[i] = pre;
        pre *= nums[i];
    }

    int post = 1;
    for(int i=numsSize-1; i>=0; i--) {
        result[i] *= post;
        post *= nums[i];
    }

    return result;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int value;
    int index;
} Pair;

typedef struct {
    Pair* data;
    int front;
    int rear;
    int size;
} Deque;

// Create a new deque
Deque* createDeque(int size) {
    Deque* deque = (Deque*)malloc(sizeof(Deque));
    deque->data = (Pair*)malloc(size * sizeof(Pair));
    deque->front = 0;
    deque->rear = -1;
    deque->size = 0;
    return deque;
}

// Push a new element to the back of the deque
void pushBack(Deque* deque, int value, int index) {
    while (deque->size > 0 && value >= deque->data[deque->rear].value) {
        deque->rear--;
        deque->size--;
    }
    deque->rear++;
    deque->data[deque->rear].value = value;
    deque->data[deque->rear].index = index;
    deque->size++;
}

// Pop elements from the front of the deque
void popFront(Deque* deque, int index) {
    if (deque->size > 0 && deque->data[deque->front].index == index) {
        deque->front++;
        deque->size--;
    }
}

// Calculate the maximum sliding window
int* maxSlidingWindow(int* nums, int numsSize, int k, int* returnSize) {
    // Check if the input array is empty
    if (numsSize == 0) {
        *returnSize = 0;
        return NULL;
    }

    // Calculate the size of the result array
    *returnSize = numsSize - k + 1;

    // Allocate memory for the result array
    int* result = (int*)malloc((*returnSize) * sizeof(int));

    // Create a deque (double-ended queue) to efficiently track maximum elements
    Deque* deque = createDeque(numsSize);

    // Iterate through the input array
    for (int i = 0; i < numsSize; i++) {
        // Push the current element to the deque, maintaining the maximum at the front
        pushBack(deque, nums[i], i);

        // Check if the window has reached the required size
        if (i >= k - 1) {
            // Store the maximum element in the result array
            result[i - k + 1] = deque->data[deque->front].value;

            // Pop elements from the front of the deque that are outside the current window
            popFront(deque, i - k + 1);
        }
    }

    // Free memory allocated for the deque
    free(deque->data);
    free(deque);

    // Return the result array containing maximum elements in each sliding window
    return result;
}

