/**
 * Given two strings s and t, return true if s is a subsequence of t, or false
 * otherwise. A subsequence of a string is a new string that is formed from the
 * original string by deleting some (can be none) of the characters without
 * disturbing the relative positions of the remaining characters. (i.e., "ace"
 * is a subsequence of "abcde" while "aec" is not).
 *
 * Example 1:

 * Input: s = "abc", t = "ahbgdc"
 * Output: true
 *
 * Example 2:
 *
 * Input: s = "axc", t = "ahbgdc"
 * Output: false
 *
 * Constraints:
 *
 * 0 <= s.length <= 100
 * 0 <= t.length <= 104
 * s and t consist only of lowercase English letters.
 *
 * Space: O(1)
 * Time: O(n)
 */

bool isSubsequence(char * s, char * t){
    char *s_char = s;
    char *t_char = t;

    while (*s_char != 0) {
        if (*t_char == 0) {
            return false;
        }
        else if (*s_char == *t_char) {
            ++s_char;
        }

        ++t_char;
    }

    return true;
}

/**
 * Given a string s which consists of lowercase or uppercase letters, return the
 * length of the longest palindrome that can be built with those letters.
 *
 * Letters are case sensitive, for example, "Aa" is not considered a palindrome
 * here.
 *
 * Constraints:
 *
 * 1 <= s.length <= 2000
 * s consists of lowercase and/or uppercase English letters only.
 *
 * Space: O(1)
 * Time: O(n)
 */

int longestPalindrome(char *s) {
    int chars_seen[128] = { 0 };

    for (char *s_char = s; *s_char; ++s_char)
        ++chars_seen[*s_char];

    int odd = 0;
    int sum = 0;
    for (int i = 'A'; i <= 'z'; ++i) {
        if (chars_seen[i] % 2) {
            odd = 1;
            sum += chars_seen[i] - 1;
        } else {
            sum += chars_seen[i];
        }
    }

    sum += odd;

    return sum;
}

bool canPartition(int* nums, int numsSize) {
    int totalSum = 0;
    for (int i = 0; i < numsSize; i++) {
        totalSum += nums[i];
    }

    if (totalSum % 2 != 0) {
        return false; // If the total sum is odd, we cannot partition equally
    }

    int targetSum = totalSum / 2;
    bool dp[targetSum + 1]; // dp[i] represents whether a subset with sum i is possible

    // Initialize dp array
    for (int i = 0; i <= targetSum; i++) {
        dp[i] = false;
    }
    dp[0] = true; // Empty subset can always achieve sum 0

    // Dynamic programming approach
    for (int i = 0; i < numsSize; i++) {
        for (int j = targetSum; j >= nums[i]; j--) {
            dp[j] = dp[j] || dp[j - nums[i]];
        }
    }

    return dp[targetSum];
}

int characterReplacement(char * s, int k){
    int count[26] = {0};
    int left = 0, right = 0, maxCount = 0;

    while (right < strlen(s)) {
        count[s[right] - 'A']++;
        maxCount = max(maxCount, count[s[right] - 'A']);
        right++;
        if (right - left - maxCount > k) {
            count[s[left] - 'A']--;
            left++;
        }
    }
    return right - left;
}

