 */
int* findDisappearedNumbers(int* nums, int numsSize, int* returnSize){
    int* disappearedNumbers = (int*)malloc(numsSize * sizeof(int)); // Allocate space for the worst case
    *returnSize = 0; // Points to the first empty index in the array

    // Mark available numbers as negative
    for(int i = 0; i < numsSize; i++)
    {
        int index = abs(nums[i]);
        nums[index - 1] = -1 * abs(nums[index - 1]);
    }

    // Find unmarked numbers (disappeared numbers)
    for(int i = 0; i < numsSize; i++)
    {
        if(nums[i] > 0)
        {
            disappearedNumbers[(*returnSize)++] = i + 1;
        }
    }

    return disappearedNumbers;
}

/*
Determine the perimeter of the island.

Space: O(1)
Time: O(n²)
*/


int islandPerimeter(int** grid, int gridSize, int* gridColSize){
    int stripes = 0;
    for (int i=0; i<gridSize; i++) {
        for (int j=0; j<gridColSize[i]; j++) {
            if (grid[i][j]==1) {
                stripes += 4;
                if (i>0 && grid[i-1][j]==1)  // Common stripe at the top
                    stripes -= 2;
                if (j>0 && grid[i][j-1]==1) // Common stripe on the left
                    stripes -= 2;
            }
        }
    }
    return stripes;
}

int findTargetSumWays(int* nums, int numsSize, int target) {
    int sum = 0;
    for (int i = 0; i < numsSize; i++) {
        sum += nums[i];
    }
    if (target > sum || target < -sum) {
        return 0;
    }

    int n = numsSize;
    int dp[n + 1][2 * sum + 1];
    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= 2 * sum; j++) {
            dp[i][j] = 0;
        }
    }
    dp[0][sum] = 1;

    for (int i = 0; i < n; i++) {
        for (int j = nums[i]; j <= 2 * sum - nums[i]; j++) {
            if (dp[i][j]) {
                dp[i + 1][j + nums[i]] += dp[i][j];
                dp[i + 1][j - nums[i]] += dp[i][j];
            }
        }
    }

    return dp[n][sum + target];
}

