// as 0 <= nums1[i], nums2[i] <= 104
Hash *InitHash() {
    Hash *h = (Hash*)calloc(INIT_HASH_SIZE, sizeof(Hash));
    assert(h);
    for (int i = 0; i < INIT_HASH_SIZE; i++) {
        h[i].key = -1;
    }
