}

Hash *NewHash(int key, int value) {
    Hash *h = (Hash*)malloc(sizeof(Hash));
    assert(h);
    h->key = key;
    h->value = value;
    h->next = NULL;
    return h;
}

int HashKey(int key) {
    while(key < 0) key += INIT_HASH_SIZE;
    return (key % INIT_HASH_SIZE);
}

void SetHash(Hash *root, int key, int value) {
    assert(root);
    Hash *h = &root[HashKey(key)];
    if (h->key == -1) {
        h->key = key;
        h->value = value;
    } else if (h->key == key) {
        h->value = value;
    } else {
        while (h) {
            if (h->key == key) {
                h->value = value;
                return;
            } else if (!h->next) {
                h->next = NewHash(key, value);
                return;
            }
            h = h->next;
        }
    }
}

