*/

int change(int amount, int* coins, int coinsSize){
    if (coinsSize==0) { // Take care of extreme cases
        return amount==0;
    }
    int* dp = calloc((amount+1), sizeof(int));
    dp[0] = 1; // One way to give zero
    for (int i=0; i<coinsSize; i++) {
        for (int j=coins[i]; j<=amount; j++) {
