    } else if (h->key == key) {
        h->count++;
    } else {
        while (h) {
            if (h->key == key) {
                h->count++;
                return;
            } else if (!h->next) {
                h->next = NewHash(key);
                return;
            }
            h = h->next;
        }
    }
}

