}

bool checkInclusion(char * s1, char * s2){
    const int m = strlen(s1);
    const int n = strlen(s2);

    if (m > n) {
        return false;
    }

    int count[26] = {0};
    for (int i = 0; i < m; i++) {
        count[s1[i] - 'a']++;
        count[s2[i] - 'a']--;
    }

    if (isPermutation(count)) {
        return true;
    }

    for (int i = m; i < n; i++) {
        count[s2[i] - 'a']--;
        count[s2[i - m] - 'a']++;
        if (isPermutation(count)) {
            return true;
        }
    }
    return false;
}

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     struct TreeNode *left;
 *     struct TreeNode *right;
 * };
 */

bool isSame(struct TreeNode* p, struct TreeNode* q) {

    if (p == NULL && q == NULL) {
        return true;
    }
    if ((p == NULL || q == NULL) || (p -> val != q -> val)) {
        return false;
    }
    return (isSame(p -> left, q -> left) && isSame(p -> right, q -> right));
}


bool isSubtree(struct TreeNode* root, struct TreeNode* subRoot){

    if (root == NULL) {
        return false;
    }

    bool compareTree = false;
    if (root -> val == subRoot -> val) {
        compareTree = isSame(root, subRoot);
    }
    return (isSubtree(root -> left, subRoot) || isSubtree(root -> right, subRoot) || compareTree);
}

/**
 * Given the root of an n-ary tree, return the preorder traversal of its nodes'
 * values.
 *
 * Nary-Tree input serialization is represented in their level order traversal.
 * Each group of children is separated by the null value (See examples)
 *
 * Constraints:
 *
 * The number of nodes in the tree is in the range [0, 104].
 * 0 <= Node.val <= 10^4
 * The height of the n-ary tree is less than or equal to 1000.
 *
 * Definition for a Node.
 * struct Node {
 *     int val;
 *     int numChildren;
 *     struct Node** children;
 * };
 *
 * Note: The returned array must be malloced, assume caller calls free().
 *
 * Space: O(n)
 * Time: O(n)
 */

void traverse(struct Node* root, int *ret, int* index) {
    if (!root)
        return;

    ret[(*index)++] = root->val;

    for (int i = 0; i < root->numChildren; ++i)
        traverse(root->children[i], ret, index);
}

int* preorder(struct Node* root, int* returnSize) {
    int *ret = malloc(10000 * sizeof(int));
    *returnSize = 0;
    traverse(root, ret, returnSize);
    return ret;
}

/*
Given an integer array flowerbed containing 0's and 1's, where 0 means empty and 1 means not
empty, and an integer n, return if n new flowers can be planted in the flowerbed without
violating the no-adjacent-flowers rule.

Space: O(1)
Time: O(n)
*/

bool canPlaceFlowers(int* flowerbed, int flowerbedSize, int n){
    int cpt = 0; // Count the number of flowers that can be added
    int i=0;
    while (i<flowerbedSize) {
        if ((i+1)==flowerbedSize) { // To avoid 'index out of range'
            if (flowerbed[i]==0) {
                cpt++;
            }
            i++;
        } else if (flowerbed[i]==0) {
            if (flowerbed[i+1]==0) {
                cpt++;
                i += 2;
            } else {
                i += 3;
            }
        } else {
            i += 2;
        }
    }
    return cpt>=n;
}

/*
You are given two binary trees root1 and root2.
Return the merged tree

Time: O(n)
Space: O(1) As we reuse the trees
*/

struct TreeNode* mergeTrees(struct TreeNode* root1, struct TreeNode* root2){
    if (root1==NULL)
        return root2;
    else if (root2==NULL)
        return root1;
    root1->val += root2->val;
    root1->left = mergeTrees(root1->left, root2->left);
    root1->right = mergeTrees(root1->right, root2->right);
    return root1;
}

int leastInterval(char *tasks, int tasksSize, int n) {
    int taskCount[26] = {0};

    for (int i = 0; i < tasksSize; i++) {
        taskCount[tasks[i] - 'A']++;
    }

    int maxTaskFreq = 0;
    int numMaxTasks = 0;

    for (int i = 0; i < 26; i++) {
        if (taskCount[i] > maxTaskFreq) {
            maxTaskFreq = taskCount[i];
            numMaxTasks = 1;
        } else if (taskCount[i] == maxTaskFreq) {
            numMaxTasks++;
        }
    }

    int intervals = (maxTaskFreq - 1) * (n + 1) + numMaxTasks;

    return (intervals > tasksSize) ? intervals : tasksSize;
}

/*
Given a string s, return the number of palindromic substrings in it.
A string is a palindrome when it reads the same backward as forward.
A substring is a contiguous sequence of characters within the string.
Time: O(n^2)
Space: O(1)
*/

int countSubstrings(char * s){
    int cpt=0;
    int x,y;

    for (int i=0; s[i]!='\0'; i++){
        cpt++; // s[i] is a palindrom
        x=i-1;
        y=i+1;
        while (x>=0 && s[y]!='\0' && s[x]==s[y]){ // Odd length palindromic substring
            cpt++;
            x--;
            y++;
        }
        x=i;
        y=i+1;
        while (x>=0 && s[y]!='\0' && s[x]==s[y]){ // Even length palindromic substring
            cpt++;
            x--;
            y++;
        }
    }
    return cpt;
}

