int dfs(int** grid, int n, int m, int i, int j) {
    int cpt=1;
    grid[i][j]=0;
    if (i>0 && grid[i-1][j]==1)
        cpt += dfs(grid, n, m, i-1, j);
    if (j>0 && grid[i][j-1]==1)
        cpt += dfs(grid, n, m, i, j-1);
    if (i<(n-1) && grid[i+1][j]==1)
        cpt += dfs(grid, n, m, i+1, j);
    if (j<(m-1) && grid[i][j+1]==1)
        cpt += dfs(grid, n, m, i, j+1);
    return cpt;
}

