    char *k = key;
    int domain = 0;
    int i;

    for (i = 0; i < len; i++) {
        if (!domain && email[i] == '.') {
            continue;
        }
        if (email[i] == '+') {
            while(i < len && email[i] != '@') {
                i++;
            }
        }
        if (email[i] == '@') {
            domain = 1;
        }
        *k++ = email[i];
    }
    *k = '\0';

    return key;
}

