/*
Given a sequence of words written in the alien language, and the
order of the alphabet, return true if and only if the given words
are sorted lexicographically in this alien language.

Space: O(1)
Time: O(n*m)
(Where n is the number of words and m the average length of the elements in words)
*/


bool isAlienSorted(char ** words, int wordsSize, char * order){
    int alphabet[26] = {0};
    for (int i=0; i<26; i++)
        alphabet[order[i] - 'a'] = i;
    for (int i=1; i<wordsSize; i++) { // We compare words[i-1] and words[i]
        int j=0;
        while (words[i-1][j]!='\0' && words[i][j]!='\0') { // Iterates through all letters of words
            int v_i_1 = alphabet[words[i-1][j] - 'a'];
            int v_i = alphabet[words[i][j] - 'a'];
            if (v_i_1 != v_i) {
                if (v_i_1>v_i){
                    return false;
                }
                break;
            }
            j++;
        }
        if (words[i-1][j]!='\0' && words[i][j] == '\0'){ // If words[i] is shorter than words[i-1]
            return false;
        }
    }
    return true;
}

typedef struct {
    int x;
    int y;
} Point;

// Function to calculate the Euclidean distance from origin
double distance(Point p) {
    return sqrt(p.x * p.x + p.y * p.y);
}

// Function to compare two points based on distance
int compare(const void* a, const void* b) {
    Point* pointA = (Point*)a;
    Point* pointB = (Point*)b;

    double distanceA = distance(*pointA);
    double distanceB = distance(*pointB);

    if (distanceA < distanceB) return -1;
    if (distanceA > distanceB) return 1;
    return 0;
}

// Function to find k closest points to origin
int** kClosest(int** points, int pointsSize, int* pointsColSize, int k, int* returnSize, int** returnColumnSizes) {
    Point* pointArr = (Point*)malloc(pointsSize * sizeof(Point));
    for (int i = 0; i < pointsSize; i++) {
        pointArr[i].x = points[i][0];
        pointArr[i].y = points[i][1];
    }

    qsort(pointArr, pointsSize, sizeof(Point), compare);

    int** result = (int**)malloc(k * sizeof(int*));
    *returnSize = k;
    *returnColumnSizes = (int*)malloc(k * sizeof(int));

    for (int i = 0; i < k; i++) {
        result[i] = (int*)malloc(2 * sizeof(int));
        result[i][0] = pointArr[i].x;
        result[i][1] = pointArr[i].y;
        (*returnColumnSizes)[i] = 2;
    }

    free(pointArr);

    return result;
}

const int OBSTACLE = -1, EMPTY = 0, START = 1, END = 2;
int uniquePathsIII(int** grid, int gridSize, int* gridColSize){
    int startRow, startCol, endRow, endCol,
        toVisit = 0, visited = 0, R = gridSize, C = gridColSize[0];
    for(int row = 0; row < R; row++)
        for(int col = 0; col < C; col++) {
            //dereference the value of the current cell
            int cell = grid[row][col];
            if(cell != OBSTACLE) {
                //all non obstacle cells must be visited
                toVisit++;
                //remember start and end cells
                if(cell == START) {
                    startRow = row;
                    startCol = col;
                } else if(cell == END) {
                    endRow = row;
                    endCol = col;
                }
            } else
                //obstacles can be considered visited cells
                visited |= 1 << (row*C + col);
        }

    //The starting state is an empty path which will visit the start cell next
    return solve(R, C, endRow, endCol, visited, toVisit, startRow, startCol);
}

int solve(int R, int C, int endRow, int endCol, int visited, int toVisit, int row, int col){
    toVisit--;
    //base case, we are at the end cell.
    if(row == endRow && col == endCol)
        return !toVisit;

    //add current cell to visited set
    visited |= 1 << (row*C + col);

    //count paths which go through all other valid neighbor cells.
    int ret = 0;
    if(row > 0 && !(visited & (1 << ((row - 1)*C + col))))
        ret += solve(R, C, endRow, endCol, visited, toVisit, row - 1, col);
    if(row + 1 < R && !(visited & (1 << ((row + 1)*C + col))))
        ret += solve(R, C, endRow, endCol, visited, toVisit, row + 1, col);
    if(col > 0 && !(visited & (1 << (row*C + col - 1))))
        ret += solve(R, C, endRow, endCol, visited, toVisit, row, col - 1);
    if(col + 1 < C && !(visited & (1 << (row*C + col + 1))))
        ret += solve(R, C, endRow, endCol, visited, toVisit, row, col + 1);
    return ret;
}

