int* addToArrayForm(int* A, int ASize, int K, int* returnSize) {
    // Calculate the maximum size of the result array
    int maxSize = (ASize > 6) ? ASize + 2 : 8;  // Maximum 6 digits in K, plus 2 for potential carry.

    // Create the result array
    int* result = (int*)malloc(maxSize * sizeof(int));

    // Initialize variables
    int carry = 0;
    int i = ASize - 1;
    int j = 0;

    // Perform the addition
    while (i >= 0 || K > 0 || carry > 0) {
        int sum = carry;
        if (i >= 0) {
            sum += A[i];
            i--;
        }
        if (K > 0) {
            sum += K % 10;
            K /= 10;
        }

        result[j] = sum % 10;
        carry = sum / 10;
        j++;
    }

    // Reverse the result array
    int left = 0;
    int right = j - 1;
    while (left < right) {
        int temp = result[left];
        result[left] = result[right];
        result[right] = temp;
        left++;
        right--;
    }

    *returnSize = j;
    return result;
}

int directions[4][2] = {{-1, 0}, {0, 1}, {1, 0}, {0, -1}};

bool rotting_process(int** grid, int rows, int cols, int timestamp) {
    bool continue_process = false;
    for (int row = 0; row < rows; row++) {
        for (int col = 0; col < cols; col++) {
            if (grid[row][col] == timestamp) {
                for (int i = 0; i < 4; i++) {
                    int r = row + directions[i][0];
                    int c = col + directions[i][1];
                    if (rows > r && r >= 0 && cols > c && c >= 0) {
                        if (grid[r][c] == 1) {
                            grid[r][c] = timestamp + 1;
                            continue_process = true;
                        }
                    }
                }
            }
        }
    }
    return continue_process;
}

int orangesRotting(int** grid, int gridSize, int* gridColSize){

    int rows = gridSize;
    int cols = gridColSize[0];

    int timestamp = 2;
    while (rotting_process(grid, rows, cols, timestamp)) {
        timestamp += 1;
    }

    for (int row = 0; row < rows; row++) {
        for (int col = 0; col < cols; col++) {
            if (grid[row][col] == 1) {
                return -1;
            }
        }
    }
    return timestamp - 2;
}

int maxUncrossedLines(int* nums1, int nums1Size, int* nums2, int nums2Size) {
    int dp[nums1Size + 1][nums2Size + 1];

    for (int i = 0; i <= nums1Size; i++) {
        for (int j = 0; j <= nums2Size; j++) {
            if (i == 0 || j == 0)
                dp[i][j] = 0;
            else if (nums1[i - 1] == nums2[j - 1])
                dp[i][j] = dp[i - 1][j - 1] + 1;
            else
                dp[i][j] = fmax(dp[i - 1][j], dp[i][j - 1]);
        }
    }

    return dp[nums1Size][nums2Size];
}

