    int dp[n];
    for (int i = 0; i < n; ++i) {
        dp[i] = -1e9;
    }

    for (int i = n - 1; i >= 0; --i) {
        int take = 0;
        for (int k = 0; k < 3 && i + k < n; ++k) {
            take += stoneValue[i + k];
            dp[i] = (dp[i] > take - ((i + k + 1 < n) ? dp[i + k + 1] : 0)) ? dp[i] : take - ((i + k + 1 < n) ? dp[i + k + 1] : 0);
        }
    }

    char *result = (char *)malloc(6 * sizeof(char)); // "Alice" or "Bob" or "Tie" plus null terminator
    if (dp[0] > 0) {
        strcpy(result, "Alice");
    } else if (dp[0] < 0) {
        strcpy(result, "Bob");
    } else {
        strcpy(result, "Tie");
    }
    return result;
}

/*
Given a binary tree root, a node X in the tree is named good if in the path from root to X there are no nodes with a value greater than X.
Return the number of good nodes in the binary tree.
Time: O(n)
Space: O(log(h)) Where h is the height of the tree
*/

int nbGood(struct TreeNode* root, int m) {
    if (root==NULL)
        return 0;
    if (root->val >= m)
        return 1+nbGood(root->left, root->val)+nbGood(root->right, root->val);
    return nbGood(root->left, m)+nbGood(root->right, m);
}

int goodNodes(struct TreeNode* root){
    return nbGood(root, INT_MIN);
}

int isVowel(char c) {
    return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
}

int maxVowels(char* s, int k) {
    int windowSum = 0;
    int len = strlen(s);
    int maxVowelCount;

    // calculate for the first window
    for (int i = 0; i < k; i++) {
        windowSum += isVowel(s[i]);
    }
    maxVowelCount = windowSum;


    for (int i = k; i < len; i++) {
        // remove the first ekem of the previous window and add the next element
        windowSum = windowSum - isVowel(s[i - k]) + isVowel(s[i]);
        if (windowSum > maxVowelCount) {
            maxVowelCount = windowSum;
        }
    }
    return maxVowelCount;
}

