int maxSumMinProduct(int* nums, int numsSize) {
    long long res = 0;
    long long dp[numsSize + 1];
    long long st[numsSize + 1];

    dp[0] = 0;
    for (int i = 0; i < numsSize; ++i) {
        dp[i + 1] = dp[i] + nums[i];
    }

    int st_top = -1;

    for (int i = 0; i <= numsSize; ++i) {
        while (st_top >= 0 && (i == numsSize || nums[st[st_top]] > nums[i])) {
            int j = st[st_top--];
            res = max(res, (long long)nums[j] * (dp[i] - dp[st_top < 0 ? 0 : st[st_top] + 1]));
        }
        st[++st_top] = i;
    }

    return (int)(res % MOD);
}

bool mergeTriplets(int** triplets, int tripletsSize, int* tripletsColSize, int* target, int targetSize) {
    int x = 0, y = 0, z = 0;

    for (int i = 0; i < tripletsSize; i++) {
        if (triplets[i][0] <= target[0] && triplets[i][1] <= target[1] && triplets[i][2] <= target[2]) {
            x = (x > triplets[i][0]) ? x : triplets[i][0];
            y = (y > triplets[i][1]) ? y : triplets[i][1];
            z = (z > triplets[i][2]) ? z : triplets[i][2];
        }
    }

    return (x == target[0] && y == target[1] && z == target[2]);
}

/*

Space: O(n²) (due to recursives calls)
Time: O(n²)
*/

bool dfs_test(int** grid1, int** grid2, int i, int j, int n, int m) {
    // Test if the island in grid2 is entirely in grid1 and delete the island in grid2
    bool ans = (grid1[i][j] == 1);
    grid2[i][j] = 0;
    if (i>0 && grid2[i-1][j]==1)
        ans = dfs_test(grid1, grid2, i-1, j, n ,m) && ans;
    if (j>0  && grid2[i][j-1]==1)
        ans = dfs_test(grid1, grid2, i, j-1, n ,m) && ans;
    if (i<(n-1)  && grid2[i+1][j]==1)
        ans = dfs_test(grid1, grid2, i+1, j, n ,m) && ans;
    if (j<(m-1)  && grid2[i][j+1]==1)
        ans = dfs_test(grid1, grid2, i, j+1, n ,m) && ans;
    return ans;
}

int countSubIslands(int** grid1, int grid1Size, int* grid1ColSize, int** grid2, int grid2Size, int* grid2ColSize){
    int cpt=0;
    for (int i=0; i<grid1Size; i++) {
        for (int j=0; j<grid1ColSize[i]; j++) {
            if (grid2[i][j]==1) {
                // Test if the island in grid2 is contained in an island in grid1
                if (dfs_test(grid1, grid2, i, j, grid1Size, grid1ColSize[i])){
                    cpt++;
                }
            }
        }
    }
    return cpt;
}

/**
