int minSwaps(char * s){
    int extraClosingBrackets = 0;
    int maxExtraClosingBrackets = 0;
    size_t sLen = strlen(s);

    for(size_t i = 0; i < sLen; i++)
    {
        if(s[i] == ']')
        {
            extraClosingBrackets += 1;
        }
        else
        {
            extraClosingBrackets -= 1;
        }

        maxExtraClosingBrackets  = max(maxExtraClosingBrackets, extraClosingBrackets);
    }

    return (maxExtraClosingBrackets + 1) / 2;
}

int upperBound(int *arr, int size, int target) {
    int left = 0, right = size - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (arr[mid] <= target) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return left;
}

int* longestObstacleCourseAtEachPosition(int* obstacles, int obstaclesSize, int* returnSize) {
    int* lis = (int*)malloc(obstaclesSize * sizeof(int));
    int* result = (int*)malloc(obstaclesSize * sizeof(int));
    *returnSize = obstaclesSize;

    int lisSize = 0;

    for (int i = 0; i < obstaclesSize; ++i) {
        int x = obstacles[i];
        if (lisSize == 0 || lis[lisSize - 1] <= x) {
            lis[lisSize] = x;
            result[i] = lisSize + 1;
            lisSize++;
        } else {
            int idx = upperBound(lis, lisSize, x);
            lis[idx] = x;
            result[i] = idx + 1;
        }
    }

    free(lis);
    return result;
}

/*
You want to rearrange the elements in the array such that every element
in the rearranged array is not equal to the average of its neighbors

Space: O(n)
Time: O(nlog(n)) (quicksort)
*/

int cmp(const void* a, const void* b) {
    return *(int*)a - *(int*)b;
}
int* rearrangeArray(int* nums, int numsSize, int* returnSize){
    int* ans = malloc(sizeof(int)*numsSize);
    *returnSize = numsSize;
    qsort(nums, numsSize, sizeof(int), cmp);
    int i, j=0;
    for (i=1; i<numsSize; i+=2) { // Put numbers in odd indexes
        ans[i] = nums[j];
        j++;
    }
    for (i=0; i<numsSize; i+=2) { // Put numbers in even indexes
        ans[i] = nums[j];
        j++;
    }
    return ans;
}

int cmp(const void* a, const void* b) {
    return *(int*)a - *(int*)b;
}

int min(int a, int b){
    if(a > b) return b;
    return a;
}

int minimumDifference(int* nums, int numsSize, int k) {
    if (k == 1) return 0;

    qsort(nums, numsSize, sizeof(int), cmp);
    int res = 1e5;
    int l = 0;
    int r = k - 1;

    while (r < numsSize)
    {
        res = min(res, nums[r] - nums[l]);
        l += 1;
        r += 1;
    }

    return res;
}

typedef struct hash_entry {
    double* ratio;            /* we'll use this field as the key */
    long long count;
    UT_hash_handle hh;      /* makes this structure hashable */
} hash_entry;

long long interchangeableRectangles(int** rectangles, int rectanglesSize, int* rectanglesColSize){
    hash_entry* ratioCountMap = NULL;
    long long res = 0;

    for(size_t i = 0; i < rectanglesSize; i++)
    {
        // Calculate the ratio (W / H)
        double* ratio = (double*)malloc(sizeof(double));
        *ratio = (double)rectangles[i][0] / rectangles[i][1];

        hash_entry* retrievedMapEntry;
        HASH_FIND_PTR(ratioCountMap, ratio, retrievedMapEntry);

        // If the ratio already exists in the map then increment its count
        if(retrievedMapEntry)
        {
            // Free the allocated memory for the ratio
            free(ratio);
            retrievedMapEntry->count += 1;
        }
        else
        {
            // If the ratio doesn't exist in the map then create a new map entry for it and add it to the map
            hash_entry* mapEntryToAdd = (hash_entry*)malloc(sizeof(hash_entry));
            mapEntryToAdd->ratio = ratio;
            mapEntryToAdd->count = 1;
            HASH_ADD_KEYPTR(hh, ratioCountMap, mapEntryToAdd->ratio, sizeof(double), mapEntryToAdd);
        }
    }

    for (hash_entry* retrievedMapEntry = ratioCountMap; retrievedMapEntry != NULL; retrievedMapEntry = retrievedMapEntry->hh.next)
    {
        res += (retrievedMapEntry->count * (retrievedMapEntry->count - 1)) / 2;
    }

    return res;
}

int palSize(char *s, int size, int mask) {
    int left = 0, right = size, res = 0;
    while (left <= right) {
        if ((mask & (1 << left)) == 0) {
            left++;
        } else if ((mask & (1 << right)) == 0) {
            right--;
        } else if (s[left] != s[right]) {
            return 0;
        } else {
            res += 1 + (left++ != right--);
        }
    }
    return res;
}

int max(int a, int b) {
    if (a > b) return a;
    return b;
}

int maxProduct(char * s) {
    int n = strlen(s);
    int dp[4096] = {}, res = 0, mask = (1 << n) - 1;
    int i, j;

    for (i = 1; i <= mask; i++) {
        dp[i] = palSize(s, n, i);
    }

    for (i = mask; i > 0; i--) {
        if (dp[i] == 0) continue;
        for(j = mask ^ i; j > 0; j = (j - 1) & (mask ^ i)) {
            if (dp[j] == 0) continue;
            res = max(res, dp[i] * dp[j]);
        }
    }
    return res;
}

long long mostPoints(int** questions, int questionsSize, int* questionsColSize) {
    int n = questionsSize;
    long long* dp = (long long*)malloc((n + 1) * sizeof(long long));

    for (int i = 0; i <= n; i++) {
        dp[i] = 0;
    }

    for (int i = n - 1; i >= 0; i--) {
        int points = questions[i][0];
        int jump = questions[i][1];
        dp[i] = (points + dp[(jump + i + 1) < n ? (jump + i + 1) : n]) > dp[i + 1] ? (points + dp[(jump + i + 1) < n ? (jump + i + 1) : n]) : dp[i + 1];
    }

    long long result = dp[0];
    free(dp);
    return result;
}

int countGoodStrings(int low, int high, int zero, int one) {
    int mod = 1000000007;
    int* dp = (int*)malloc((high + 1) * sizeof(int));

    dp[0] = 1;
    int res = 0;

    for (int i = 1; i <= high; ++i) {
        dp[i] = 0;

        if (i >= zero) {
            dp[i] = (dp[i] + dp[i - zero]) % mod;
        }

        if (i >= one) {
            dp[i] = (dp[i] + dp[i - one]) % mod;
        }

        if (i >= low) {
            res = (res + dp[i]) % mod;
        }
    }

    free(dp);
    return res;
}
